-- Each trainee gets its own active flag.
--
-- Siblings share one account (users), and a trainee's status used to BE that
-- account's status. Deactivating one child therefore deactivated the account:
-- every brother and sister showed as inactive, and the parent's portal login was
-- removed. The account now stays active while any of its trainees is.

-- 1. (Generated by Prisma.)
ALTER TABLE "trainee_profiles" ADD COLUMN     "is_active" BOOLEAN NOT NULL DEFAULT true;

-- 2. Until now a trainee was active exactly when its account was; start from that,
-- so no trainee changes status in this migration.
UPDATE "trainee_profiles" t
SET "is_active" = u."is_active"
FROM "users" u
WHERE u."id" = t."user_id"
  AND t."is_active" IS DISTINCT FROM u."is_active";
